import {test,expect,type Page} from '@playwright/test'
type InvitationFixture={room:string;group:boolean;title:string;invitePreviewFailures:number;inviteUnavailable:boolean;holdInvitePreview:boolean;invitePreviewPending:boolean;releaseInvitePreview:()=>void;holdInviteJoin:boolean;inviteJoinPending:boolean;releaseInviteJoin:()=>void;inviteCalls:{action:string;token:string}[]}
type Preview=Window&{playerChatFixture:InvitationFixture;switchNavigationOwner:()=>void;openSyntheticLink:(url:string)=>void}
const origin='http://127.0.0.1:4283',token='b'.repeat(64),link='https://www.tenaceiq.com/chats/join?invite='+token
async function calls(page:Page){return page.evaluate(()=>(window as unknown as Preview).playerChatFixture.inviteCalls)}
const dialog=(page:Page)=>page.locator('dialog.player-chats-dialog')
async function groupDraft(page:Page){
 await page.getByRole('navigation',{name:'Main navigation'}).getByRole('button',{name:/^Chats/}).click()
 await page.getByRole('button',{name:'New chat',exact:true}).click()
 await dialog(page).getByRole('button',{name:'Group',exact:true}).click()
 await dialog(page).getByRole('textbox',{name:'Group name'}).fill('Friday doubles')
 await dialog(page).getByRole('checkbox',{name:'Jamie',exact:true}).check()
 await dialog(page).getByText('Use a contact invite',{exact:true}).click()
 await dialog(page).getByRole('textbox',{name:'Invite link',exact:true}).fill(link)
}
export function registerInvitationRecoveryCases(firstParty:(page:Page)=>Promise<void>){
 for(const width of [320,390])test('Invitation recovery retries the same group after sign-in at '+width+'px',async({page},info)=>{
  await firstParty(page);await page.setViewportSize({width,height:844})
  await page.goto(origin+'/?signedOut=1&player-chat=1&group-invite=1&invite-preview-fail=1&large=1&link='+encodeURIComponent(link))
  await page.locator('[data-link-open]').click()
  await page.locator('.welcome-account form input[name=email]').fill('preview@example.test')
  await page.locator('.welcome-account form input[name=password]').fill('synthetic-password')
  await page.locator('.welcome-account form button').click()
  const view=dialog(page)
  await expect(view.getByRole('button',{name:'Retry invite',exact:true})).toBeEnabled()
  expect(await calls(page)).toEqual([{action:'preview',token}])
  await view.screenshot({path:info.outputPath('invite-retry-'+width+'.png')})
  expect(await view.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true)
  await view.getByRole('button',{name:'Retry invite',exact:true}).click()
  await expect(view.getByText('Friday practice',{exact:true})).toBeVisible()
  expect(await calls(page)).toEqual([{action:'preview',token},{action:'preview',token}])
  await view.getByRole('button',{name:'Join group',exact:true}).click()
  await expect(view.getByRole('heading',{name:'Friday practice',exact:true})).toBeVisible()
  await view.getByRole('button',{name:'Close',exact:true}).click()
  await expect(view).toHaveCount(0)
  await expect(page.locator('.app-navigation [data-screen="teams"]')).toHaveAttribute('aria-current','page')
  await expect(page.getByRole('button',{name:/^Friday practice/})).toBeVisible()
  expect((await calls(page)).filter(row=>row.action==='join')).toEqual([{action:'join',token}])
 })
 test('Invitation recovery keeps the new group draft and selected contacts after retry',async({page})=>{
  await firstParty(page);await page.goto(origin+'/?player-chat=1&invite-preview-fail=1');await groupDraft(page)
  const view=dialog(page)
  await view.getByRole('button',{name:'Review invite',exact:true}).click()
  await expect(view.getByRole('button',{name:'Retry invite',exact:true})).toBeEnabled()
  await view.getByRole('button',{name:'Retry invite',exact:true}).click()
  await expect(view.getByText('Morgan',{exact:true})).toBeVisible()
  await view.getByRole('button',{name:'Save player',exact:true}).click()
  await expect(view.getByRole('textbox',{name:'Group name'})).toHaveValue('Friday doubles')
  await expect(view.getByRole('checkbox',{name:'Jamie',exact:true})).toBeChecked()
  await expect(view.getByRole('checkbox',{name:'Morgan',exact:true})).toBeChecked()
  expect(await calls(page)).toEqual([{action:'preview',token},{action:'preview',token},{action:'join',token}])
 })
 test('Invitation recovery cancels a slow contact preview without losing the group draft',async({page})=>{
  await firstParty(page);await page.goto(origin+'/?player-chat=1');await groupDraft(page)
  await page.evaluate(()=>(window as unknown as Preview).playerChatFixture.holdInvitePreview=true)
  const view=dialog(page)
  await view.getByRole('button',{name:'Review invite',exact:true}).click()
  await expect.poll(()=>page.evaluate(()=>(window as unknown as Preview).playerChatFixture.invitePreviewPending)).toBe(true)
  await expect(view.getByRole('button',{name:'Back to new group',exact:true})).toBeEnabled()
  await view.getByRole('button',{name:'Back to new group',exact:true}).click()
  await expect(view.getByRole('textbox',{name:'Group name'})).toHaveValue('Friday doubles')
  await expect(view.getByRole('checkbox',{name:'Jamie',exact:true})).toBeChecked()
  await view.getByRole('textbox',{name:'Group name'}).fill('Saturday doubles')
  await page.evaluate(()=>(window as unknown as Preview).playerChatFixture.releaseInvitePreview())
  await expect.poll(()=>page.evaluate(()=>(window as unknown as Preview).playerChatFixture.invitePreviewPending)).toBe(false)
  await expect(view.getByRole('textbox',{name:'Group name'})).toHaveValue('Saturday doubles')
  await expect(view.getByRole('button',{name:'Save player',exact:true})).toHaveCount(0)
  expect(await calls(page)).toEqual([{action:'preview',token}])
 })
 test('Invitation recovery closes an unavailable shared invite to Chats without joining',async({page})=>{
  await firstParty(page);await page.goto(origin+'/?player-chat=1&group-invite=1')
  await expect(page.locator('.lab-scoreboard')).toBeVisible()
  await page.evaluate(url=>{const w=window as unknown as Preview;w.playerChatFixture.inviteUnavailable=true;w.openSyntheticLink(url)},link)
  const view=dialog(page)
  await expect(view).toContainText('This invitation is no longer available.')
  await expect(view.getByRole('button',{name:'Join group',exact:true})).toHaveCount(0)
  await view.getByRole('button',{name:'Close',exact:true}).click()
  await expect(view).toHaveCount(0)
  await expect(page.locator('.app-navigation [data-screen="teams"]')).toHaveAttribute('aria-current','page')
  expect(await calls(page)).toEqual([{action:'preview',token}])
 })
 test('Invitation recovery closes a shared team preview to Chats without joining',async({page})=>{
  await firstParty(page)
  const teamLink='https://www.tenaceiq.com/team-room/join?token=44444444-4444-4444-8444-444444444444'
  await page.goto(origin+'/?link='+encodeURIComponent(teamLink))
  const view=page.getByRole('dialog',{name:'Join a team',exact:true})
  await expect(view.getByRole('heading',{name:'Baseline Aces',exact:true})).toBeVisible()
  await view.getByRole('button',{name:'Close',exact:true}).click()
  await expect(view).toHaveCount(0)
  await expect(page.locator('.app-navigation [data-screen="teams"]')).toHaveAttribute('aria-current','page')
  expect(await page.evaluate(()=>(window as unknown as {firstPartyTeamFixture:{requests:string[]}}).firstPartyTeamFixture.requests.filter(action=>action.startsWith('invite:')))).toEqual(['invite:preview'])
 })
 test('Invitation recovery ignores a cancelled preview after a newer invite is unavailable',async({page})=>{
  await firstParty(page);await page.goto(origin+'/?player-chat=1');await groupDraft(page)
  await page.evaluate(()=>(window as unknown as Preview).playerChatFixture.holdInvitePreview=true)
  const view=dialog(page)
  await view.getByRole('button',{name:'Review invite',exact:true}).click()
  await expect.poll(()=>page.evaluate(()=>(window as unknown as Preview).playerChatFixture.invitePreviewPending)).toBe(true)
  await view.getByRole('button',{name:'Back to new group',exact:true}).click()
  await page.evaluate(()=>(window as unknown as Preview).playerChatFixture.inviteUnavailable=true)
  const nextToken='c'.repeat(64)
  await view.getByText('Use a contact invite',{exact:true}).click()
  await view.getByRole('textbox',{name:'Invite link',exact:true}).fill('https://www.tenaceiq.com/chats/join?invite='+nextToken)
  await view.getByRole('button',{name:'Review invite',exact:true}).click()
  await expect(view).toContainText('This invitation is no longer available.')
  await page.evaluate(()=>(window as unknown as Preview).playerChatFixture.releaseInvitePreview())
  await expect.poll(()=>page.evaluate(()=>(window as unknown as Preview).playerChatFixture.invitePreviewPending)).toBe(false)
  await expect(view.getByRole('button',{name:'Save player',exact:true})).toHaveCount(0)
  await expect(view).toContainText('This invitation is no longer available.')
  expect(await calls(page)).toEqual([{action:'preview',token},{action:'preview',token:nextToken}])
 })
 test('Invitation recovery can close a slow shared group preview without joining or reopening',async({page})=>{
  await firstParty(page);await page.goto(origin+'/?player-chat=1&group-invite=1')
  await expect(page.locator('.lab-scoreboard')).toBeVisible()
  await page.evaluate(url=>{const w=window as unknown as Preview;w.playerChatFixture.holdInvitePreview=true;w.openSyntheticLink(url)},link)
  await expect.poll(()=>page.evaluate(()=>(window as unknown as Preview).playerChatFixture.invitePreviewPending)).toBe(true)
  await page.keyboard.press('Escape')
  await expect(dialog(page)).toHaveCount(0)
  await expect(page.locator('.app-navigation [data-screen="teams"]')).toHaveAttribute('aria-current','page')
  await page.evaluate(()=>(window as unknown as Preview).playerChatFixture.releaseInvitePreview())
  await expect.poll(()=>page.evaluate(()=>(window as unknown as Preview).playerChatFixture.invitePreviewPending)).toBe(false)
  await expect(dialog(page)).toHaveCount(0)
  expect(await calls(page)).toEqual([{action:'preview',token}])
 })
 test('Invitation recovery refreshes teams after an unconfirmed join and restores clean cancellations',async({page})=>{
  await firstParty(page);await page.goto(origin)
  await expect(page.locator('.lab-scoreboard')).toBeVisible()
  await page.evaluate(()=>(window as unknown as {chatUnreadFixture:{empty:boolean}}).chatUnreadFixture.empty=true)
  await page.getByRole('button',{name:'Compete',exact:true}).click()
  const join=page.getByRole('button',{name:'Join team',exact:true})
  const view=page.getByRole('dialog',{name:'Join a team',exact:true})
  const review=async()=>{
   await join.click();await view.getByLabel('Team invite', {exact:true}).fill('44444444-4444-4444-8444-444444444444')
   await view.getByRole('button',{name:'Review invite',exact:true}).click()
   await expect(view.getByRole('heading',{name:'Baseline Aces',exact:true})).toBeVisible()
  }
  await review();await view.getByRole('button',{name:'Close',exact:true}).click()
  await expect(join).toBeFocused()
  await expect(page.locator('.app-navigation [data-screen="compete"]')).toHaveAttribute('aria-current','page')
  await review()
  await page.evaluate(()=>(window as unknown as {firstPartyTeamFixture:{loseJoinReply:boolean}}).firstPartyTeamFixture.loseJoinReply=true)
  await view.getByRole('button',{name:'Join as player',exact:true}).click()
  await expect(view.getByRole('button',{name:'Retry same join',exact:true})).toBeEnabled()
  await view.getByRole('button',{name:'Close',exact:true}).click()
  await expect(view).toHaveCount(0)
  await expect(page.locator('.app-navigation [data-screen="teams"]')).toHaveAttribute('aria-current','page')
  await expect(page.getByRole('button',{name:/^Baseline Aces/}).first()).toBeVisible()
  expect(await page.evaluate(()=>(window as unknown as {firstPartyTeamFixture:{requests:string[]}}).firstPartyTeamFixture.requests.filter(action=>action.startsWith('invite:')))).toEqual(['invite:preview','invite:preview','invite:join'])
 })
 test('Invitation recovery keeps a submitted group join open until its confirmation arrives',async({page})=>{
  await firstParty(page);await page.goto(origin+'/?player-chat=1&group-invite=1&link='+encodeURIComponent(link))
  const view=dialog(page)
  await expect(view.getByRole('button',{name:'Join group',exact:true})).toBeEnabled()
  await page.evaluate(()=>(window as unknown as Preview).playerChatFixture.holdInviteJoin=true)
  await view.getByRole('button',{name:'Join group',exact:true}).click()
  await expect.poll(()=>page.evaluate(()=>(window as unknown as Preview).playerChatFixture.inviteJoinPending)).toBe(true)
  await expect(view.getByRole('button',{name:'Close',exact:true})).toBeDisabled()
  await page.keyboard.press('Escape');await expect(view).toBeVisible()
  await page.evaluate(()=>(window as unknown as Preview).playerChatFixture.releaseInviteJoin())
  await expect(view.getByRole('heading',{name:'Friday practice',exact:true})).toBeVisible()
  await view.getByRole('button',{name:'Close',exact:true}).click()
  await expect(view).toHaveCount(0)
  await expect(page.locator('.app-navigation [data-screen="teams"]')).toHaveAttribute('aria-current','page')
  expect(await calls(page)).toEqual([{action:'preview',token},{action:'join',token}])
 })
 test('Invitation recovery preserves Updates return and the join guard through a chat',async({page})=>{
  await firstParty(page);await page.goto(origin+'/?player-chat=1&group-invite=1')
  await expect(page.locator('.lab-scoreboard')).toBeVisible()
  const id='aaaa0000-0000-4000-8000-000000000099'
  await page.evaluate(id=>{
   const w=window as unknown as Preview&{updatesFixture:{rows:Record<string,unknown>[]};firstPartyUpdatesFixture:{coachNotices:Record<string,unknown>[]}}
   const f=w.playerChatFixture;f.group=true;f.title='Friday practice'
   w.firstPartyUpdatesFixture.coachNotices.push({...w.updatesFixture.rows[0],id,title:'Friday group message',href:'/chats?room='+f.room,conversation_id:f.room,notification_type:'message',read_at:null})
  },id)
  await page.locator('.native-updates-entry').click()
  const updates=page.getByRole('dialog',{name:'Updates',exact:true}),opener=updates.locator('[data-open-update="'+id+'"]'),view=dialog(page)
  const openInvitation=async()=>{
   await opener.click();await expect(view.getByRole('heading',{name:'Friday practice',exact:true})).toBeVisible()
   await view.getByRole('button',{name:'Back to players & groups',exact:true}).click()
   await view.getByRole('textbox',{name:'Have an invite link?',exact:true}).fill(link)
   await view.getByRole('button',{name:'Review invite',exact:true}).click()
   await expect(view.getByRole('button',{name:'Join group',exact:true})).toBeEnabled()
  }
  await openInvitation()
  await view.getByRole('button',{name:'Back to players & groups',exact:true}).click()
  await view.getByRole('button',{name:'Close',exact:true}).click()
  await expect(view).toHaveCount(0);await expect(opener).toBeFocused()
  await openInvitation()
  await page.evaluate(()=>(window as unknown as Preview).playerChatFixture.holdInviteJoin=true)
  await view.getByRole('button',{name:'Join group',exact:true}).click()
  await expect.poll(()=>page.evaluate(()=>(window as unknown as Preview).playerChatFixture.inviteJoinPending)).toBe(true)
  // Exercise the parent controller's Back path used by native Android Back.
  await updates.evaluate(el=>el.dispatchEvent(new Event('cancel',{cancelable:true})))
  await expect(view).toBeVisible();await expect(view.getByRole('button',{name:'Back to players & groups',exact:true})).toBeDisabled()
  await page.evaluate(()=>(window as unknown as Preview).playerChatFixture.releaseInviteJoin())
  await expect(view.getByRole('heading',{name:'Friday practice',exact:true})).toBeVisible()
  await updates.evaluate(el=>el.dispatchEvent(new Event('cancel',{cancelable:true})))
  await expect(view.getByRole('heading',{name:'Players & groups',exact:true})).toBeVisible()
  await updates.evaluate(el=>el.dispatchEvent(new Event('cancel',{cancelable:true})))
  await expect(view).toHaveCount(0);await expect(updates).toBeVisible();await expect(opener).toBeFocused()
  expect(await calls(page)).toEqual([{action:'preview',token},{action:'preview',token},{action:'join',token}])
 })
}
